#!/usr/bin/env python3
"""Emit `guard_store_wfcap_schema_sql.rs` from the Python schema constants.

The resident re-validates the workflow-capability schema on every operation
exactly as the Python startup does, so the statement text and the owned
object list are copied from `store_workflow_capabilities_schema` rather than
retyped. `--check` fails when the checked-in Rust file has drifted.
"""

from __future__ import annotations

import sys
from pathlib import Path

from codex_plugin_scanner.guard import store_workflow_capabilities_schema as schema

TARGET = Path(__file__).resolve().parents[2] / "src" / "guard_store_wfcap_schema_sql.rs"


def render() -> str:
    lines = [
        "//! Generated by `testdata/guard_store/generate_workflow_capability_schema.py`;",
        "//! do not edit. Statement text and owned objects mirror the Python schema.",
        "",
        f"pub(crate) const STATEMENTS: [&str; {len(schema._SCHEMA_STATEMENTS)}] = [",
    ]
    for statement in schema._SCHEMA_STATEMENTS:
        assert '"##' not in statement
        lines.append(f'    r##"{statement}"##,')
    lines += ["];", "", f"pub(crate) const OBJECTS: [(&str, &str); {len(schema._OBJECT_NAMES)}] = ["]
    for kind, name in schema._OBJECT_NAMES:
        lines.append(f'    ("{kind}", "{name}"),')
    lines += ["];", ""]
    return "\n".join(lines)


def main() -> int:
    rendered = render()
    if "--check" in sys.argv:
        return 0 if TARGET.read_text(encoding="utf-8") == rendered else 1
    TARGET.write_text(rendered, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
